      // a × a суурьтай, k давхарга жижиг кубээс тогтох хайрцаг (налуу проекц). Нэг давхаргад a·a = a², k = a үед куб: a³.
      // Гүний нэг нэгж → баруун тийш 0.42, дээш 0.3. x-ийг 1-ээр шилжүүлсэн (0 нь x мужид орохгүй тул босоо тэнхлэг зургийн дундуур гарахгүй).
