          f: [{ h: 'Ижил хуваарьтай', m: '\\dfrac{a}{c}+\\dfrac{b}{c}=\\dfrac{a+b}{c}', n: '$\\dfrac{5}{12}+\\dfrac{1}{12}=\\dfrac{6}{12}=\\dfrac{1}{2}$ — хариуг хураав.' },
            { h: 'Өөр хуваарьтай', m: '\\dfrac{3}{4}-\\dfrac{1}{6}=\\dfrac{9}{12}-\\dfrac{2}{12}=\\dfrac{7}{12}', n: '$\\text{ХБЕХ}(4,6)=12$. Нэмэлт үржигдэхүүн: $12\\div 4=3$, $\\ 12\\div 6=2$.' }],
