      // процентын шугам. Цэгийг аравтын бутархайн шугамын дагуу чирнэ (v → x = L0 + LW·v), V714 бутархайнууд дээр зогсоно.
      const V714 = [[1, 20], [1, 10], [1, 8], [1, 5], [1, 4], [3, 10], [1, 3], [3, 8], [2, 5], [1, 2], [3, 5], [5, 8], [2, 3], [7, 10], [3, 4], [4, 5], [7, 8], [9, 10], [1, 1]];
