        if (b > 1) for (let i = 0; i < b; i++) { const q0 = pt(2 * Math.PI * i / b, R0714), q = pt(2 * Math.PI * i / b, R714); L.push([q0[0], q0[1], q[0], q[1], C.V, 0]); }
