        const hl = 12, h = 0.145, ns = 7, Q = [[-hl, -h], [hl - ns, -h], [hl, 0], [hl - ns, h], [-hl, h], [-hl, -h]];
        for (let y = -h + 0.016; y < h; y += 0.032) L.push([O715 + cx - d * hl, cy + y, O715 + cx + d * (hl - ns * Math.abs(y) / h), cy + y, col, 0]);
        for (let i = 0; i < 5; i++) L.push([O715 + cx + d * Q[i][0], cy + Q[i][1], O715 + cx + d * Q[i + 1][0], cy + Q[i + 1][1], C.K, 0]);
