          o: ['$30$ км', '$90$ км', '$120$ км', '$210$ км'], c: 0,
          why: '$\\dfrac{3}{5}=0.6$. Хоёр өдөрт замын $0.3+0.6=0.9$ хэсгийг явсан тул үлдсэн нь $1-0.9=0.1$ хэсэг: $300\\cdot 0.1=30$ км.',
